const COLORS=['mint','coral','violet','gold'];
const COLOR_NAMES={mint:'MINT',coral:'KORALLE',violet:'VIOLETT',gold:'GOLD'};
const ACTIONS={skip:{name:'BREAK',sub:'AUSSETZEN',symbol:'Ⅱ'},reverse:{name:'ABSEILEN',sub:'RICHTUNG',symbol:'↶'},swap:{name:'BETA TAUSCH',sub:'HANDTAUSCH',symbol:'⇄'},draw2:{name:'PUMPED',sub:'+2',symbol:'✦',draw:2},draw6:{name:'TROMMEL WIRBEL',sub:'+6',symbol:'≋',draw:6},wild4:{name:'DYNO',sub:'+4',symbol:'↗',draw:4,wild:true},wild8:{name:'CHALK BLAST',sub:'+8',symbol:'✺',draw:8,wild:true},wild12:{name:'DOUBLE KICK',sub:'+12',symbol:'ϟ',draw:12,wild:true},wild16:{name:'WALL COLLAPSE',sub:'+16',symbol:'▰',draw:16,wild:true},wild20:{name:'WALL OF SOUND',sub:'+20',symbol:'◉',draw:20,wild:true},all3:{name:'CRASH SOLO',sub:'ALLE +3',symbol:'♬',wild:true},route:{name:'ROUTENBAU',sub:'FARBE',symbol:'⬢',wild:true},shield:{name:'FREE SOLO',sub:'SCHUTZ',symbol:'◇',wild:true}};
ACTIONS.mult2={name:'DOUBLE TROUBLE',sub:'×2 STRAFE',symbol:'×2',multiplier:2,wild:true};
ACTIONS.mult4={name:'QUAD BLAST',sub:'×4 STRAFE',symbol:'×4',multiplier:4,wild:true};
ACTIONS.flush={name:'ROUTE FLASH',sub:'FARBE WEG',symbol:'⚡',wild:true};
ACTIONS.burst={name:'CAMPUS RUN',sub:'BIS ZU 5',symbol:'≋',wild:true};
ACTIONS.burn={name:'CHALK FIRE',sub:'ALLE -3',symbol:'♨',wild:true};
ACTIONS.bonfire={name:'GRIFF LAWINE',sub:'HALBE HAND WEG',symbol:'☄',wild:true};
const NAMES=['DU','BEATBOT','BETABANDIT','ROUTESETTER'];
const QUOTES={1:['Mehr Cowbell. Weniger Hoffnung.','+20. Halt dich gut fest.','War das schon dein Fill?','Ich spiele im 7/8-Takt. Du nicht.'],2:['Deine Hand ist sehr… informativ.','Diese Beta war offensichtlich.','Ich wusste, dass du das legst.','Chalk ersetzt keine Technik.'],3:['Meine Wand. Meine Regeln.','Den Griff gab es eben noch nicht.','Route umgeschraubt. Pech.','Du kletterst meine Restekiste.']};
let state={},soundOn=true,audioCtx,selectedSuspect=null;
const $=s=>document.querySelector(s);
const els={hand:$('#playerHand'),discard:$('#discardPile'),draw:$('#drawPile'),playerCount:$('#playerCount'),turn:$('#turnPill'),penalty:$('#penaltyMeter'),penaltyValue:$('#penaltyValue'),routeName:$('#routeName'),routeIndicator:$('#routeIndicator'),log:$('#eventLog'),playerMood:$('#playerMood'),crux:$('#cruxBtn'),toast:$('#toast'),suspicion:$('#suspicionValue'),suspicionFill:$('#suspicionFill'),accuse:$('#accuseBtn'),suspectHint:$('#suspectHint')};

function createDeck(){const deck=[];let id=0;COLORS.forEach(color=>{deck.push({id:id++,color,type:'number',value:0});for(let copy=0;copy<2;copy++)for(let n=1;n<=9;n++)deck.push({id:id++,color,type:'number',value:n});['skip','reverse','draw2'].forEach(action=>{deck.push({id:id++,color,type:'action',action});deck.push({id:id++,color,type:'action',action})});['swap','draw6'].forEach(action=>deck.push({id:id++,color,type:'action',action}))});['wild4','wild8','wild12','mult2'].forEach(action=>{for(let i=0;i<2;i++)deck.push({id:id++,color:'wild',type:'action',action})});['wild16','wild20','all3','route','shield','mult4','flush','burst','burn','bonfire'].forEach(action=>deck.push({id:id++,color:'wild',type:'action',action}));return shuffle(deck)}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function newGame(){const deck=createDeck(),hands=[[],[],[],[]];for(let r=0;r<7;r++)hands.forEach(h=>h.push(deck.pop()));let first=deck.pop();while(first.type!=='number'){deck.unshift(first);first=deck.pop()}state={deck,hands,discard:[first],currentColor:first.color,turn:0,direction:1,pending:0,busy:false,declared:false,over:false,log:[],suspicion:0,lastCheater:null,shield:[false,false,false,false],bonusTurn:null,round:0,handOffset:0};selectedSuspect=null;addLog('Vier Kletternde. Eine Route. <b>Du beginnst.</b>');setSpeech(1,'Tempo halten.');setSpeech(2,'Ich kenne die Beta.');setSpeech(3,'Meine Wand. Meine Regeln.');render()}
function topCard(){return state.discard.at(-1)}
function isDraw(card){return card.type==='action'&&!!ACTIONS[card.action]?.draw}
function isMultiplier(card){return card.type==='action'&&!!ACTIONS[card.action]?.multiplier}
function playable(card){if(state.pending>0)return isDraw(card)||isMultiplier(card);if(isMultiplier(card))return false;const top=topCard();return card.color==='wild'||card.color===state.currentColor||(card.type==='number'&&top.type==='number'&&card.value===top.value)||(card.type==='action'&&top.type==='action'&&card.action===top.action)}
function nextIndex(from=state.turn,steps=1){let n=from;for(let i=0;i<steps;i++)n=(n+state.direction+4)%4;return n}
function cardHTML(card,hidden=false){if(hidden)return '<i class="bot-card" aria-hidden="true"></i>';const action=card.type==='action'?ACTIONS[card.action]:null;const center=action?`<span class="symbol">${action.symbol}</span><span class="action-name">${action.name}</span><span class="action-sub">${action.sub}</span>`:`<span class="value">${card.value}</span><span class="action-sub">GRIFF</span>`;const corner=action?(action.draw?`+${action.draw}`:action.symbol):card.value;return `<span class="corner">${corner}</span><span class="card-center">${center}</span>`}
function countLabel(n){return n.toLocaleString('de-DE')}
function botDelay(actor){const n=state.hands[actor].length;return n>1000?60:n>300?110:n>100?220:n>40?500:1700+Math.random()*700}
function cardLabel(c){return c.type==='number'?`${COLOR_NAMES[c.color]} ${c.value}`:`${ACTIONS[c.action].name} ${ACTIONS[c.action].sub}`}
function render(){const playerTotal=state.hands[0].length;els.playerCount.textContent=countLabel(playerTotal);els.playerCount.dataset.digits=String(playerTotal).length;els.playerCount.title=`${countLabel(playerTotal)} Karten`;for(let i=1;i<4;i++){const total=state.hands[i].length;$(`#botCount${i}`).textContent=countLabel(total);$(`#botCount${i}`).dataset.digits=String(total).length;$(`#botCount${i}`).title=`${countLabel(total)} Karten`;$(`#botHand${i}`).innerHTML=state.hands[i].slice(0,9).map(()=>cardHTML(null,true)).join('');document.querySelector(`[data-suspect="${i}"]`).classList.toggle('active',state.turn===i)}els.hand.innerHTML='';const windowSize=160;state.handOffset=Math.min(state.handOffset||0,Math.max(0,playerTotal-windowSize));const visible=state.hands[0].slice(state.handOffset,state.handOffset+windowSize);visible.forEach((card,localIndex)=>{const i=state.handOffset+localIndex;const b=document.createElement('button');b.className=`game-card ${card.color}`;b.innerHTML=cardHTML(card);b.disabled=state.turn!==0||state.busy||!playable(card);b.setAttribute('aria-label',cardLabel(card));b.onclick=()=>playerPlay(i);els.hand.appendChild(b)});const top=topCard();els.discard.innerHTML=`<div class="game-card ${top.color}">${cardHTML(top)}</div>`;els.turn.classList.toggle('bot-turn',state.turn!==0);els.turn.innerHTML=`<span></span>${state.turn===0?'DU BIST DRAN':NAMES[state.turn]+' DENKT'}`;els.penalty.hidden=!state.pending;els.penaltyValue.textContent=state.pending;els.routeName.textContent=COLOR_NAMES[state.currentColor];els.routeIndicator.querySelector('i').style.background=`var(--${state.currentColor})`;els.crux.hidden=!(state.hands[0].length===1&&state.turn===0&&!state.declared);els.draw.disabled=state.turn!==0||state.busy;els.log.innerHTML=state.log.slice(-7).reverse().map((x,i)=>`<div class="log-item"><span class="log-time">${String(state.log.length-i).padStart(2,'0')} / SESSION</span>${x}</div>`).join('');els.suspicion.textContent=`${state.suspicion}%`;els.suspicionFill.style.width=`${state.suspicion}%`;els.accuse.disabled=!selectedSuspect||state.suspicion<30||state.turn!==0;els.suspectHint.textContent=selectedSuspect?`${NAMES[selectedSuspect]} ausgewählt`:'Erst einen Bot auswählen';const range=$('#handRange');if(range)range.textContent=playerTotal>windowSize?`${state.handOffset+1}–${Math.min(state.handOffset+windowSize,playerTotal)} / ${countLabel(playerTotal)}`:`${countLabel(playerTotal)} KARTEN`;if($('#handPrev'))$('#handPrev').disabled=state.handOffset===0;if($('#handNext'))$('#handNext').disabled=state.handOffset+windowSize>=playerTotal}
function playerPlay(index){const hand=state.hands[0];if(state.busy||state.turn!==0||!playable(hand[index]))return;if(hand.length===1&&!state.declared){showToast('CRUX VERGESSEN — +4!');drawCards(0,4);impact('+4',true);state.declared=false;render();return}playCard(hand.splice(index,1)[0],0)}
function playCard(card,actor){state.discard.push(card);if(actor===0)state.declared=false;addLog(`${actor===0?'<b>Du</b>':NAMES[actor]} spielt <b>${cardLabel(card)}</b>.`);hitSound(card);animateImpact(card);if(card.color==='wild'){if(actor===0){state.busy=true;render();setTimeout(()=>$('#colorModal').classList.add('open'),180);return}state.currentColor=bestColor(actor)}else state.currentColor=card.color;resolveCard(card,actor)}
function resolveCard(card,actor){const action=card.action;if(isDraw(card)){state.pending=Math.min(9999,state.pending+ACTIONS[action].draw);addLog(`Der Strafstapel steht bei <b>+${state.pending}</b>.`);if(action==='wild12')state.bonusTurn=actor;if(action==='wild16')state.direction*=-1}if(isMultiplier(card)){state.pending=Math.min(9999,state.pending*ACTIONS[action].multiplier);addLog(`${NAMES[actor]} multipliziert die Strafe: <b>×${ACTIONS[action].multiplier} = +${state.pending}</b>.`);impact(`×${ACTIONS[action].multiplier}!`,true)}if(action==='all3'){for(let i=0;i<4;i++)if(i!==actor)drawCards(i,3);impact('ALLE +3',true)}if(action==='shield'){state.shield[actor]=true;addLog(`${NAMES[actor]} hat jetzt <b>Free-Solo-Schutz</b>.`)}if(action==='flush')shedColor(actor,Infinity,'ROUTE FLASH');if(action==='burst')shedColor(actor,Math.min(25,5+Math.floor(state.hands[actor].length/100)),'CAMPUS RUN');if(action==='burn')burnTable();if(action==='bonfire')burnHalf(actor);if(action==='swap')swapHands(actor);if(action==='reverse')state.direction*=-1;const steps=action==='skip'?2:1;state.turn=nextIndex(actor,steps);if(checkWin(actor))return;updateMoods();render();if(state.turn!==0)setTimeout(botTurn,botDelay(state.turn))}
function chooseColor(color){$('#colorModal').classList.remove('open');state.currentColor=color;state.busy=false;addLog(`Du setzt die Route auf <b>${COLOR_NAMES[color]}</b>.`);resolveCard(topCard(),0)}
function bestColor(actor){const counts=Object.fromEntries(COLORS.map(c=>[c,0]));state.hands[actor].forEach(c=>{if(c.color!=='wild')counts[c.color]++});return [...COLORS].sort((a,b)=>counts[b]-counts[a])[0]}
function swapHands(actor){const targets=[0,1,2,3].filter(i=>i!==actor);const target=actor===0?(selectedSuspect||targets.sort((a,b)=>state.hands[a].length-state.hands[b].length)[0]):targets.sort((a,b)=>state.hands[a].length-state.hands[b].length)[0];[state.hands[actor],state.hands[target]]=[state.hands[target],state.hands[actor]];addLog(`${NAMES[actor]} tauscht die Hand mit <b>${NAMES[target]}</b>.`);setSpeech(actor||target,'Das war jetzt meine Hand.')}
function shedColor(actor,limit,label){const hand=state.hands[actor],removed=[];for(let i=hand.length-1;i>=0&&removed.length<limit;i--)if(hand[i].color===state.currentColor)removed.push(...hand.splice(i,1));if(removed.length){state.discard.push(...removed);addLog(`${NAMES[actor]} wirft mit <b>${label} ${removed.length} Karten</b> ab.`);impact(`-${removed.length}`,removed.length>4)}}
function burnHalf(actor){const hand=state.hands[actor],amount=Math.floor(hand.length/2);for(let n=0;n<amount;n++)hand.splice(Math.floor(Math.random()*hand.length),1);addLog(`${NAMES[actor]} löst eine <b>GRIFFLAWINE</b> aus und verbrennt ${amount} Karten.`);impact(`🔥 -${amount}`,true)}
function burnTable(){for(let actor=0;actor<4;actor++){const hand=state.hands[actor],amount=Math.min(3,Math.max(0,hand.length-1));for(let n=0;n<amount;n++)hand.splice(Math.floor(Math.random()*hand.length),1)}addLog('<b>CHALK FIRE:</b> Alle verbrennen bis zu 3 Karten.');impact('🔥 ALLE -3',true)}
function drawCards(who,count){const hand=state.hands[who],before=hand.length;for(let i=0;i<count;i++){if(!state.deck.length)recycleDeck();if(!state.deck.length)state.deck=createDeck();hand.push(state.deck.pop())}const actual=hand.length-before;addLog(`${who===0?'<b>Du ziehst</b>':NAMES[who]+' zieht'} <b>${actual} ${actual===1?'Griff':'Griffe'}</b>.`);return actual}
function recycleDeck(){const keep=state.discard.pop();state.deck=shuffle(state.discard);state.discard=[keep]}
function takePenalty(who){if(state.shield[who]){state.shield[who]=false;state.pending=0;state.bonusTurn=null;addLog(`${NAMES[who]} blockt alles mit <b>FREE SOLO</b>.`);impact('BLOCK!',true);state.turn=nextIndex(who);return}const amount=state.pending||1;drawCards(who,amount);if(who===0&&amount>=8){els.hand.classList.add('chalk-blind');setTimeout(()=>els.hand.classList.remove('chalk-blind'),1200)}impact(`${who===0?'':NAMES[who]+' '}+${amount}`,amount>5);state.pending=0;const bonus=state.bonusTurn;state.bonusTurn=null;state.turn=bonus??nextIndex(who)}
function handleDraw(){if(state.turn!==0||state.busy)return;takePenalty(0);state.declared=false;updateMoods();render();if(state.turn!==0)setTimeout(botTurn,botDelay(state.turn))}
function botTurn(){if(state.over||state.turn===0)return;const actor=state.turn;state.round++;maybeCheat(actor);render();const choices=state.hands[actor].map((c,i)=>({c,i})).filter(x=>playable(x.c));if(!choices.length){setSpeech(actor,state.pending?`Ich kassiere wirklich +${state.pending}.`:'Kein Griff. Ich ziehe.');setTimeout(()=>{takePenalty(actor);updateMoods();render();if(state.turn!==0)setTimeout(botTurn,botDelay(state.turn))},900);return}if(state.hands[actor].length<=80)choices.sort((a,b)=>scoreCard(b.c,actor)-scoreCard(a.c,actor));const choice=state.hands[actor].length>80?choices[Math.floor(Math.random()*choices.length)]:choices[Math.random()<.78?0:Math.floor(Math.random()*choices.length)];const card=state.hands[actor].splice(choice.i,1)[0];setSpeech(actor,botQuote(actor));setTimeout(()=>playCard(card,actor),Math.min(900,Math.max(80,botDelay(actor)*.4)))}
function scoreCard(c,actor){let s=isDraw(c)?ACTIONS[c.action].draw*5:0;if(c.action==='flush')s+=state.hands[actor].filter(x=>x.color===bestColor(actor)).length*6;if(c.action==='burn')s+=state.hands[actor].length>15?25:0;if(c.action==='bonfire')s+=state.hands[actor].length;if(c.color===bestColor(actor))s+=4;if(c.action==='swap'&&state.hands[actor].length>state.hands[0].length)s+=12;if(c.color==='wild')s+=3;return s}
function maybeCheat(actor){if(Math.random()>.22)return;let did=false;if(actor===1){const extra=state.hands[actor].findIndex(c=>playable(c)&&!isDraw(c));if(extra>=0&&state.hands[actor].length>2){state.hands[actor].splice(extra,1);did=true;setSpeech(actor,'Zwei Schläge zählen als einer.')}}if(actor===2){did=true;setSpeech(actor,'Deine Hand ist sehr informativ.')}if(actor===3){const idx=state.deck.findIndex(c=>isDraw(c));if(idx>=0){state.hands[actor].push(state.deck.splice(idx,1)[0]);did=true;setSpeech(actor,'Diesen Griff habe ich gefunden.')}}if(did){state.lastCheater=actor;state.suspicion=Math.min(100,state.suspicion+18+Math.floor(Math.random()*19));addLog('Am Tisch passiert etwas <b>Verdächtiges</b> …');tone(75,.22,'sawtooth',0,.06)}}
function accuse(){if(!selectedSuspect||state.suspicion<30||state.turn!==0)return;if(selectedSuspect===state.lastCheater){drawCards(selectedSuspect,8);showToast(`${NAMES[selectedSuspect]} ERWISCHT — +8!`);setSpeech(selectedSuspect,'Das war… regelkonform-ish.');state.suspicion=0;state.lastCheater=null;impact('ERWISCHT!',true)}else{drawCards(0,4);showToast('FALSCH VERDÄCHTIGT — DU +4!');setSpeech(selectedSuspect,'Schlechter Call.');state.suspicion=Math.max(0,state.suspicion-25);impact('FALSCH! +4',true)}selectedSuspect=null;document.querySelectorAll('.opponent-seat').forEach(x=>x.classList.remove('selected'));render()}
function checkWin(actor){if(state.hands[actor].length)return false;state.over=true;render();setTimeout(()=>{const win=actor===0;$('#endEyebrow').textContent=win?'ROUTE GETOPPT':'ABGEPUMPT';$('#endTitle').textContent=win?'DU HÄNGST NOCH!':`${NAMES[actor]} TOPPT!`;$('#endText').textContent=win?'Drei Bots liegen unter einem Berg Strafkarten.':'Nächstes Mal mehr Chalk. Und mehr Cowbell.';$('#endModal').classList.add('open');winSound(win)},450);return true}
function declareCrux(){if(state.hands[0].length!==1||state.turn!==0)return;state.declared=true;showToast('CRUX GERUFEN!');addLog('<b>CRUX!</b> Sauber angesagt.');tone(540,.08,'square');render()}
function setSpeech(i,text){if(i>0){$(`#speech${i}`).textContent=text;$(`#speech${i}`).title=text}}
function botQuote(i){return QUOTES[i][Math.floor(Math.random()*QUOTES[i].length)]}
function updateMoods(){els.playerMood.textContent=state.pending&&state.turn===0?`+${state.pending} kontern oder kassieren!`:state.hands[0].length<=2?'Nur noch ein Zug bis zum Top.':'Finger warm. Los geht’s.';for(let i=1;i<4;i++)$(`#botMood${i}`).textContent=state.pending&&state.turn===i?`wankt unter +${state.pending}`:state.hands[i].length>12?'komplett abgepumpt':state.hands[i].length<=2?'kurz vor dem Top':'plant den nächsten Zug'}
function addLog(t){state.log.push(t);if(state.log.length>30)state.log.shift()}
function showToast(t){els.toast.textContent=t;els.toast.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>els.toast.classList.remove('show'),1700)}
function animateImpact(c){const n=isDraw(c)?ACTIONS[c.action].draw:0;if(n>=6)impact(`+${n}`,n>=12)}
function impact(t,big=false){const e=document.createElement('div');e.className='impact';e.textContent=t;e.style.left=`${45+Math.random()*10}%`;e.style.top=`${38+Math.random()*12}%`;document.body.appendChild(e);setTimeout(()=>e.remove(),850);if(big){$('.arena').classList.remove('screen-shake');void $('.arena').offsetWidth;$('.arena').classList.add('screen-shake')}}
function ensureAudio(){if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)()}
function tone(f,d=.08,type='sine',delay=0,v=.09){if(!soundOn)return;ensureAudio();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=f;g.gain.setValueAtTime(v,audioCtx.currentTime+delay);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+delay+d);o.connect(g).connect(audioCtx.destination);o.start(audioCtx.currentTime+delay);o.stop(audioCtx.currentTime+delay+d)}
function hitSound(c){const n=isDraw(c)?ACTIONS[c.action].draw:0;tone(110,.1,'square',0,.08);tone(180+n*13,.16,'triangle',.025,.1);if(n>=8){tone(70,.28,'sawtooth',.06,.13);tone(420,.1,'square',.14,.07)}}
function winSound(win){[0,1,2,3].forEach(n=>tone((win?240:180)+n*(win?80:-15),.14,'square',n*.11,.07))}
function shiftHandWindow(delta){state.handOffset=Math.max(0,(state.handOffset||0)+delta*160);render()}
if($('#handPrev'))$('#handPrev').onclick=()=>shiftHandWindow(-1);if($('#handNext'))$('#handNext').onclick=()=>shiftHandWindow(1);
$('#startBtn').onclick=()=>{$('#startModal').classList.remove('open');ensureAudio();newGame()};$('#restartBtn').onclick=()=>{$('#endModal').classList.remove('open');newGame()};$('#rulesBtn').onclick=()=>$('#rulesModal').classList.add('open');$('#closeRules').onclick=()=>$('#rulesModal').classList.remove('open');$('#rulesModal').onclick=e=>{if(e.target.id==='rulesModal')e.currentTarget.classList.remove('open')};document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>chooseColor(b.dataset.color));els.draw.onclick=handleDraw;els.crux.onclick=declareCrux;els.accuse.onclick=accuse;document.querySelectorAll('.opponent-seat').forEach(b=>b.onclick=()=>{selectedSuspect=Number(b.dataset.suspect);document.querySelectorAll('.opponent-seat').forEach(x=>x.classList.toggle('selected',x===b));render()});$('#soundBtn').onclick=e=>{soundOn=!soundOn;e.currentTarget.querySelector('span').textContent=soundOn?'♪':'×';e.currentTarget.setAttribute('aria-label',soundOn?'Ton ausschalten':'Ton einschalten')};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#rulesModal').classList.remove('open');if(e.key===' '&&state.turn===0){e.preventDefault();handleDraw()}});newGame();
